/* 공문서(기안문 갑지) 생성: ODT, HWPX. 워드(docx)는 지원하지 않음.
 * - ODT : 부산소방 표준기안문 ODT 템플릿(로고·머리말·결재선·하단 기관정보 표)의 필드만 치환 (LibreOffice·한컴오피스에서 열림)
 * - HWPX: 같은 표준기안문 양식을 한컴오피스에서 HWPX로 변환한 템플릿의 필드만 치환 (한컴오피스에서 열림·렌더링 확인)
 *   두 형식 모두 필드 값 계산(fieldValues)과 본문 문단 구성(bodyParagraphs)을 공유합니다. */
(function (g) {
  const Z = () => g.JSZip;
  const x = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  // XML 1.0에서 허용되지 않는 제어문자 제거
  const clean = (s) => String(s ?? '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');

  /** 기안문 레이아웃 → [{t: 텍스트, s: 스타일}] */
  function layout(d) {
    const L = [];
    const add = (t, s) => L.push({ t: clean(t), s: s || 'normal' });
    add(d.orgName, 'org');
    add('', 'normal');
    add(`수신  ${d.receiver || ''}`);
    add(`(경유)${d.via ? '  ' + d.via : ''}`);
    add(`제목  ${d.title || ''}`, 'title');
    add('', 'normal');
    const body = (d.body || '').split(/\r?\n/);
    while (body.length && !body[body.length - 1].trim()) body.pop();
    const atts = (d.attachments || []).filter((a) => a.trim());
    if (!atts.length && body.length) body[body.length - 1] += '  끝.';
    body.forEach((l) => add(l));
    if (atts.length) {
      add('');
      atts.forEach((a, i) => {
        const last = i === atts.length - 1 ? '  끝.' : '';
        if (atts.length === 1) add(`붙임  ${a}${last}`);
        else add(`${i === 0 ? '붙임  ' : '      '}${i + 1}. ${a}${last}`);
      });
    }
    add('');
    add(d.sender || '', 'sender');
    add('');
    add(d.signLine || '', 'normal');
    if (d.cooperator) add(`협조자  ${d.cooperator}`);
    add(`시행  ${d.docNo || ''} (${d.date || ''})  접수  ${d.receiptNo || ''}`, 'small');
    add(`우 ${d.zip || ''} ${d.addr || ''} / 전화 ${d.tel || ''} / 전송 ${d.fax || ''} / ${d.email || ''} / ${d.publicType || '공개'}`, 'small');
    return L;
  }

  // ---------------- ODT (실제 부산소방 온나라 표준기안문 ODT 템플릿 기반) ----------------
  const ODT_TPL_B64 = '';

  function replaceCellField(xml, fieldLabel, value) {
    const escLabel = fieldLabel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const re = new RegExp('(<text:span text:style-name="([^"]+)")(?:\\/>|>[^<]*(?:<text:s[^>]*\\/>[^<]*)*<\\/text:span>)(<text:bookmark text:name="CellField\\d+¡' + escLabel + '¡[FT]"\\/>)');
    const safeVal = x(clean(value));
    return xml.replace(re, (m, openTag, st, bm) => openTag + '>' + safeVal + '</text:span>' + bm);
  }

  /** 본문 줄/붙임 목록 → 문단 배열 (ODT·HWPX 공통). 붙임이 없으면 본문 마지막 줄 끝에 '끝.' 표시 */
  function bodyParagraphs(d) {
    const lines = String(d.body || '').split(/\r?\n/);
    while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
    const atts = (d.attachments || []).map((a) => String(a).trim()).filter(Boolean);
    if (!atts.length && lines.length) lines[lines.length - 1] += '  끝.';
    if (!lines.length) lines.push('');
    const out = [];
    lines.forEach((l, i) => { out.push(l); if (i < lines.length - 1) out.push(''); });
    if (atts.length) {
      out.push('');
      atts.forEach((a, i) => {
        const end = i === atts.length - 1 ? '  끝.' : '';
        out.push(atts.length === 1 ? `붙임  ${a}${end}` : `${i === 0 ? '붙임  ' : '      '}${i + 1}. ${a}${end}`);
      });
    }
    return out;
  }

  /** 양식 필드(라벨) → 값. 입력이 비었을 때의 기본값도 여기서 정한다 (ODT·HWPX 공통) */
  function fieldValues(d) {
    const parts = (v) => String(v || '').trim().split(/\s+/);
    const dr = parts(d.drafter), rv = parts(d.reviewer), ap = parts(d.approver);
    const role = (p, label) => ({ rank: p.length > 1 ? p[0] : (p[0] ? label : ''), name: p.length > 1 ? p.slice(1).join(' ') : (p[0] || '') });
    const r2 = role(rv, '검토'), r3 = role(ap, '결재');
    return {
      '머리말': d.headSlogan || '발주는 부산기업으로, 구매는 부산상품으로, 우리가 살리는 부산경제',
      '기관명': d.orgName || '부산소방재난본부', '수신': d.receiver || '', '경유': d.via || '', '제목': d.title || '', '발신명의': d.sender || '',
      '*검토1': dr[0] || '소방사', '검토1': dr.slice(1).join(' ') || '',
      '*검토2': r2.rank, '검토2': r2.name, '*검토3': r3.rank, '검토3': r3.name,
      '협조1': d.cooperator || '', '시행번호': d.docNo || '', '시행일자': d.date || '', '접수번호': d.receiptNo || '',
      '우편번호': d.zip || '49442', '주소': d.addr || '부산광역시 사하구 장평로 270, (신평동)', '홈페이지': d.homepage || 'http://saha119.busan.go.kr',
      '전화번호': d.tel || '051-000-0000', '전송': d.fax || '051-000-0000', '전자우편': d.email || '아이디@korea.kr', '공개여부': d.publicType || '대국민 공개',
      '꼬리말': d.footSlogan || '지역상품 구매 촉진을 통한 지역경제 선순환 구조 확립',
    };
  }

  /** ODT 본문 XML. st: 템플릿 본문 문단에서 읽은 스타일·책갈피 이름 {p, a, b, bm} */
  function buildBodyXml(d, st) {
    const fmtSpaces = (t) => x(clean(t)).replace(/ {2,}|^ /g, (m) => `<text:s text:c="${m.length}"/>`);
    const paras = bodyParagraphs(d).map((line, idx) => {
      if (idx === 0) return `<text:p text:style-name="${st.p}"><text:span text:style-name="${st.a}"><text:bookmark-start text:name="${st.bm}"/>${fmtSpaces(line)}</text:span></text:p>`;
      if (!line) return `<text:p text:style-name="${st.p}"><text:span text:style-name="${st.a}"/></text:p>`;
      return `<text:p text:style-name="${st.p}"><text:span text:style-name="${st.b}">${fmtSpaces(line)}</text:span></text:p>`;
    });
    paras[paras.length - 1] = paras[paras.length - 1].replace(/<\/text:p>$/, `<text:span text:style-name="${st.a}"><text:bookmark-end text:name="${st.bm}"/></text:span></text:p>`);
    return paras.join('');
  }

  async function buildOdt(d, outType) {
    const srcZip = await Z().loadAsync(ODT_TPL_B64, { base64: true });
    let contentXml = await srcZip.file('content.xml').async('string');
    let metaXml = await srcZip.file('meta.xml').async('string');

    const fv = fieldValues(d);
    for (const label of Object.keys(fv)) contentXml = replaceCellField(contentXml, label, fv[label]);

    // 본문 영역: 첫 문단의 bookmark-start ~ 마지막 문단의 bookmark-end (문단 스타일·필드 번호는 템플릿마다 다를 수 있음)
    const bodyRe = /<text:p text:style-name="([^"]+)"><text:span text:style-name="([^"]+)"><text:bookmark-start text:name="(NormalField\d+¡본문¡[^"]*)"\/>[\s\S]*?<text:bookmark-end text:name="\3"\/><\/text:span>(?:<text:span text:style-name="[^"]+"\/>)?<\/text:p>/;
    const bm = bodyRe.exec(contentXml);
    if (!bm) throw new Error('ODT 템플릿에서 본문 영역을 찾지 못했습니다.');
    const t6 = [...bm[0].matchAll(/<text:span text:style-name="([^"]+)"/g)].map((m) => m[1]).find((n) => n !== bm[2]) || bm[2];
    contentXml = contentXml.replace(bodyRe, () => buildBodyXml(d, { p: bm[1], a: bm[2], b: t6, bm: bm[3] }));

    const zip = new (Z())();
    const mime = 'application/vnd.oasis.opendocument.text';
    zip.file('mimetype', mime, { compression: 'STORE' });
    for (const [name, entry] of Object.entries(srcZip.files)) {
      if (name === 'mimetype' || entry.dir) continue;
      if (name === 'content.xml') zip.file(name, contentXml);
      else if (name === 'meta.xml') zip.file(name, metaXml);
      else zip.file(name, await entry.async('uint8array'));
    }
    return zip.generateAsync({ type: outType || 'blob', mimeType: mime, compression: 'DEFLATE' });
  }

  // ---------------- HWPX (표준기안문 양식을 한컴오피스에서 변환한 템플릿 기반) ----------------
  // 필드 자리는 @@라벨@@ 표지로 남겨 두었고, 본문·붙임 영역(클릭 필드)은 문단을 다시 구성한다.
  const HWPX_TPL_B64 = '';

  async function buildHwpx(d, outType) {
    const src = await Z().loadAsync(HWPX_TPL_B64, { base64: true });
    let sec = await src.file('Contents/section0.xml').async('string');

    // 본문 영역: '@@본문@@' 첫 문단 ~ '@@붙임@@' 마지막 문단 (한 개의 클릭 필드로 이어져 있음)
    const iBody = sec.indexOf('@@본문@@'), iAtt = sec.indexOf('@@붙임@@');
    if (iBody < 0 || iAtt < 0) throw new Error('HWPX 템플릿에서 본문 영역을 찾지 못했습니다.');
    const pStart = sec.lastIndexOf('<hp:p ', iBody);
    const pEnd = sec.indexOf('</hp:p>', iAtt) + 7;
    const first = sec.slice(pStart, sec.indexOf('</hp:p>', iBody) + 7);
    const last = sec.slice(sec.lastIndexOf('<hp:p ', iAtt), pEnd);
    const open = /<hp:p [^>]*>/.exec(first)[0];
    const fieldEnd = (/<hp:run charPrIDRef="\d+"><hp:ctrl><hp:fieldEnd[^>]*\/><\/hp:ctrl><hp:t\/><\/hp:run>/.exec(last) || [''])[0];
    const cpText = (/<hp:run charPrIDRef="(\d+)"><hp:t>붙임/.exec(last) || [])[1] || '0';
    const t = (v) => (v ? `<hp:t>${x(clean(v))}</hp:t>` : '<hp:t/>');
    const paras = bodyParagraphs(d).map((line, i) => (i === 0
      ? first.replace('<hp:t>@@본문@@</hp:t>', () => t(line))
      : `${open}<hp:run charPrIDRef="${cpText}">${t(line)}</hp:run></hp:p>`));
    paras[paras.length - 1] = paras[paras.length - 1].replace(/<\/hp:p>$/, () => `${fieldEnd}</hp:p>`);
    sec = sec.slice(0, pStart) + paras.join('') + sec.slice(pEnd);

    const fv = fieldValues(d);
    for (const label of Object.keys(fv)) sec = sec.split(`@@${label}@@`).join(x(clean(fv[label])));

    // 패키지 재구성: mimetype 첫 항목(무압축) + 템플릿 파일 + 치환된 본문/메타
    const mime = 'application/hwp+zip';
    const zip = new (Z())();
    zip.file('mimetype', mime, { compression: 'STORE' });
    const now = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
    for (const [name, entry] of Object.entries(src.files)) {
      if (name === 'mimetype' || entry.dir) continue;
      if (name === 'Contents/section0.xml') zip.file(name, sec);
      else if (name === 'Contents/content.hpf') {
        const hpf = (await entry.async('string'))
          .replace(/<opf:title>[^<]*<\/opf:title>/, () => `<opf:title>${x(clean(d.title))}</opf:title>`)
          .replace(/(<opf:meta name="(?:CreatedDate|ModifiedDate)"[^>]*>)[^<]*/g, (m, a) => a + now);
        zip.file(name, hpf);
      } else zip.file(name, await entry.async('uint8array'));
    }
    return zip.generateAsync({ type: outType || 'blob', mimeType: mime, compression: 'DEFLATE' });
  }

  g.Doc = { layout, buildOdt, buildHwpx };
  if (typeof module !== 'undefined') module.exports = g.Doc;
})(typeof window !== 'undefined' ? window : globalThis);
